import { setThemePreferences, settleTheme } from "../helpers/theme-preferences";
import { test, expect, setThemeQuotaGating } from "../helpers/theme-browser";
import AxeBuilder from "@axe-core/playwright";

const themes = [
  ["lavender", "purple", "light"],
  ["nightbloom", "purple", "dark"],
  ["chalk", "vercel", "light"],
  ["obsidian", "vercel", "dark"],
] as const;

test("Premium summary fits every theme on desktop and mobile", async ({
  page,
}, testInfo) => {
  test.skip(testInfo.project.name !== "desktop", "Own viewport matrix");
  test.setTimeout(120_000);
  await setThemeQuotaGating(true);
  await page.route("**/api/billing/status", async (route) => {
    const response = await route.fetch();
    await route.fulfill({
      response,
      json: {
        ...(await response.json()),
        configured: true,
        checkoutEnabled: true,
        plan: "PAID",
        status: "ACTIVE",
        mode: "test",
        hasCustomer: true,
        isSuspended: false,
        paymentConfirmed: true,
        checkoutState: null,
        cancelAtPeriodEnd: false,
        cancellationPending: false,
        periodEnd: "2027-01-01T00:00:00.000Z",
        recurringAmountMinor: 599,
        recurringCurrency: "USD",
      },
    });
  });
  for (const [name, appearance, mode] of themes) {
    await setThemePreferences(page, appearance, mode);
    for (const width of [1440, 390, 320, 280]) {
      await page.emulateMedia({
        reducedMotion: width === 320 ? "no-preference" : "reduce",
      });
      await page.setViewportSize({ width: Math.max(width, 320), height: 1000 });
      await page.goto("/usage?country=US");
      const card = page.getByRole("region", { name: "Premium", exact: true });
      await expect(
        card.getByRole("heading", { name: "Included with Premium" }),
      ).toBeVisible();
      await settleTheme(page);
      await expect(card.locator("dd")).toHaveCount(0);
      await expect(card.getByText("20", { exact: true })).toHaveCount(0);
      await expect(card.getByText("300", { exact: true })).toHaveCount(0);
      await expect(
        page.getByRole("region", { name: "Daily allowance" }),
      ).toContainText("of 20 emails per UTC day");
      await expect(
        page.getByRole("region", { name: "Monthly allowance" }),
      ).toContainText("of 300 emails this billing period");
      await expect(card.getByRole("meter")).toHaveCount(0);
      await expect(card.locator("[data-localized-price]")).toHaveCount(0);
      await expect(
        card.getByRole("link", { name: "Compare plans" }),
      ).toHaveCount(0);
      await expect(
        card.getByRole("link", { name: "All Premium features" }),
      ).toHaveAttribute("href", "/pricing");
      await expect(
        card
          .getByRole("list", { name: "Included in your plan" })
          .locator("strong"),
      ).toHaveText([
        "10 recipients per campaign",
        "Unlimited saved templates",
        "CSV contact import",
        "Follow-up reminders",
      ]);
      await expect(card.getByText("role shortcuts")).toHaveCount(0);
      await expect(
        card.getByRole("button", { name: "Manage subscription" }),
      ).toHaveCount(0);
      await expect(
        card.getByRole("button", { name: "More subscription actions" }),
      ).toHaveCount(0);
      await expect(
        card.getByText("Stored recurring amount before tax:", { exact: false }),
      ).toHaveCount(0);
      await expect(
        card.getByText("Next monthly renewal:", { exact: false }),
      ).toHaveCount(0);
      await card
        .getByRole("button", { name: "Test mode", exact: true })
        .focus();
      await expect(page.getByRole("tooltip")).toContainText("no real charges");
      await page.keyboard.press("Escape");
      if (width === 280) {
        await card.locator("..").evaluate((el) => {
          el.style.width = "280px";
        });
      }
      expect(
        await card.evaluate((el) =>
          Array.from(el.querySelectorAll<HTMLElement>("*"))
            .filter(
              (child) =>
                child.clientWidth > 0 &&
                !child.classList.contains("sr-only") &&
                child.scrollWidth > child.clientWidth + 1,
            )
            .map((child) => child.textContent),
        ),
      ).toEqual([]);
      expect(
        await page.evaluate(
          () => document.documentElement.scrollWidth <= innerWidth,
        ),
      ).toBe(true);
      expect(
        (
          await new AxeBuilder({ page })
            .include("[data-usage-plan-card]")
            .analyze()
        ).violations,
      ).toEqual([]);
      await card.screenshot({
        path: testInfo.outputPath(`${name}-${width}-premium.png`),
        animations: "disabled",
        style:
          ".help-launcher, nextjs-portal { visibility: hidden !important; }",
      });
      await card
        .locator("..")
        .evaluate((el) => el.style.removeProperty("width"));
    }
  }
});

test("current plan comparison works across container sizes and themes", async ({
  page,
}, testInfo) => {
  test.skip(
    testInfo.project.name !== "desktop",
    "This test covers its own viewport matrix.",
  );
  test.setTimeout(240_000);
  await setThemeQuotaGating(true);
  await page.emulateMedia({ reducedMotion: "reduce" });
  await page.route("**/api/billing/status", async (route) => {
    const response = await route.fetch();
    const status = await response.json();
    await route.fulfill({
      response,
      json: {
        ...status,
        configured: true,
        checkoutEnabled: true,
        plan: "FREE",
        status: "NONE",
        mode: "test",
        hasCustomer: true,
        isSuspended: false,
        paymentConfirmed: false,
        periodEnd: null,
        gracePeriodEnd: null,
        recurringAmountMinor: null,
        recurringCurrency: null,
        cancelAtPeriodEnd: false,
        cancellationPending: false,
        checkoutState: null,
      },
    });
  });
  for (const [name, appearance, mode] of themes) {
    await setThemePreferences(page, appearance, mode);
    for (const width of [1920, 1366, 390]) {
      await page.setViewportSize({ width, height: 1000 });
      await page.goto("/usage?country=US");
      await expect(page.locator("html")).toHaveAttribute(
        "data-appearance",
        appearance,
      );
      await expect(page.locator("html")).toHaveAttribute("data-theme", mode);
      await expect(
        page.getByRole("heading", { name: "Free", exact: true }),
      ).toBeVisible();
      await settleTheme(page);
      const allowances = page.locator("#allowances");
      await expect(
        allowances.getByRole("heading", { name: "Daily allowance" }),
      ).toBeVisible();
      const unchanged = [
        allowances,
        page.locator("[class*='explainer']"),
        page.locator("[class*='guidance']").first(),
      ];
      for (const [index, section] of unchanged.entries()) {
        await section.screenshot({
          path: testInfo.outputPath(`${name}-${width}-section-${index}.png`),
          animations: "disabled",
          mask: [
            section.locator("time"),
            section.locator("[class*=resetPill]"),
          ],
        });
      }
      const card = page.getByRole("region", { name: "Free", exact: true });
      const summary = card.locator("[data-plan-summary]");
      const comparison = card.locator("[data-plan-comparison]");
      const strip = card.getByRole("list", { name: "Included in your plan" });
      await expect(strip.getByRole("listitem")).toHaveCount(3);
      await expect(
        summary.getByRole("heading", { name: "Included with Free" }),
      ).toBeVisible();
      await expect(
        summary.getByRole("button", { name: "Upgrade to Premium" }),
      ).toHaveCount(0);
      await expect(
        summary.getByRole("link", { name: "Compare plans" }),
      ).toHaveCount(0);
      await expect(
        comparison.getByRole("heading", { name: "More room to reach out" }),
      ).toBeVisible();
      await expect(comparison).toContainText("CSV contact import");
      await expect(comparison).toContainText("Follow-up reminders");
      await expect(
        card.getByRole("meter", { name: /Daily sending limit/ }),
      ).toHaveAttribute("aria-valuenow", "3");
      await expect(
        card.getByRole("meter", { name: /Monthly sending limit/ }),
      ).toHaveAttribute("aria-valuenow", "15");
      for (const [key, ratio] of [
        ["dailyEmails", 0.15],
        ["monthlyEmails", 0.05],
      ] as const) {
        const bar = card.locator(`[data-plan-limit="${key}"]`);
        await expect
          .poll(() =>
            bar.evaluate(
              (el) =>
                el.getBoundingClientRect().width /
                el.parentElement!.getBoundingClientRect().width,
            ),
          )
          .toBeCloseTo(ratio, 2);
      }
      const frame = await card.locator("..").boundingBox();
      const bounds = await card.boundingBox();
      const allowanceBounds = await allowances.boundingBox();
      expect(Math.abs(bounds!.width - allowanceBounds!.width)).toBeLessThan(1);
      const panels = await card.locator(":scope > *").evaluateAll((items) =>
        items.slice(0, 2).map((item) => ({
          x: item.getBoundingClientRect().x,
          y: item.getBoundingClientRect().y,
        })),
      );
      if (frame!.width <= 860) expect(panels[1].y).toBeGreaterThan(panels[0].y);
      else expect(panels[1].x).toBeGreaterThan(panels[0].x);
      await expect(card.locator("[data-localized-price]")).toContainText(
        "5.99/mo",
      );
      await expect(
        card.getByRole("link", { name: "Compare plans" }),
      ).toHaveAttribute("href", "/pricing");
      await expect(
        comparison.getByRole("button", { name: "Upgrade to Premium" }),
      ).toBeVisible();
      await card
        .getByRole("button", { name: "About access overrides" })
        .focus();
      await expect(page.getByRole("tooltip")).toContainText("access override");
      await expect(
        card.getByRole("button", { name: "More subscription actions" }),
      ).toHaveCount(0);
      await card
        .getByRole("button", { name: "Upgrade to Premium", exact: true })
        .focus();
      await expect(
        card.getByRole("button", { name: "Upgrade to Premium", exact: true }),
      ).toHaveCSS("outline-style", "solid");
      await card
        .getByRole("button", { name: "Upgrade to Premium", exact: true })
        .blur();
      expect(
        await page.evaluate(
          () => document.documentElement.scrollWidth <= innerWidth,
        ),
      ).toBe(true);
      expect((await new AxeBuilder({ page }).analyze()).violations).toEqual([]);
      await card.screenshot({
        path: testInfo.outputPath(`${name}-${width}-card.png`),
        animations: "disabled",
      });
      await page.screenshot({
        path: testInfo.outputPath(`${name}-${width}.png`),
        fullPage: true,
        animations: "disabled",
      });
    }
  }
});

test("current plan responds to its container and preserves billing actions and notices", async ({
  page,
}, testInfo) => {
  test.skip(
    testInfo.project.name !== "desktop",
    "This test covers its own viewport matrix.",
  );
  test.setTimeout(120_000);
  await page.emulateMedia({ reducedMotion: "reduce" });
  let current: Record<string, unknown> = {
    configured: true,
    checkoutEnabled: true,
    plan: "FREE",
    status: "NONE",
    mode: "test",
    hasCustomer: true,
    isSuspended: false,
    paymentConfirmed: false,
    periodEnd: null,
    gracePeriodEnd: null,
    recurringAmountMinor: null,
    recurringCurrency: null,
    cancelAtPeriodEnd: false,
    cancellationPending: false,
    checkoutState: null,
  };
  let failedLookup = false;
  await page.route("**/api/billing/status", (route) =>
    route.fulfill(failedLookup ? { status: 503, json: {} } : { json: current }),
  );
  await page.setViewportSize({ width: 1366, height: 1000 });
  await page.goto("/usage?country=US");
  const card = page.getByRole("region", { name: "Free", exact: true });
  const frame = card.locator("..");
  await expect(card).toBeVisible();
  for (const width of [
    320, 659, 660, 661, 800, 859, 860, 861, 960, 1200, 280,
  ]) {
    await frame.evaluate((el, width) => {
      el.style.width = `${width}px`;
    }, width);
    const panels = await card.locator(":scope > *").evaluateAll((items) =>
      items.map((item) => ({
        x: item.getBoundingClientRect().x,
        y: item.getBoundingClientRect().y,
      })),
    );
    if (width <= 860) expect(panels[1].y).toBeGreaterThan(panels[0].y);
    else expect(panels[1].x).toBeGreaterThan(panels[0].x);
    const overflowing = await card.evaluate((el) =>
      Array.from(el.querySelectorAll<HTMLElement>("*"))
        .filter(
          (child) =>
            child.clientWidth > 0 && child.scrollWidth > child.clientWidth + 1,
        )
        .map((child) => ({ tag: child.tagName, text: child.textContent })),
    );
    expect(overflowing, `No clipped content at ${width}px`).toEqual([]);
  }
  await frame.evaluate((el) => el.style.removeProperty("width"));
  let submitted: unknown;
  await page.route("**/api/billing/checkout", (route) => {
    submitted = route.request().postDataJSON();
    return route.fulfill({
      status: 409,
      json: {
        error: "Your previous checkout is being verified.",
        code: "CHECKOUT_PENDING",
      },
    });
  });
  await card
    .getByRole("button", { name: "Upgrade to Premium", exact: true })
    .click();
  await expect(card.getByRole("alert")).toContainText(
    "previous checkout is being verified",
  );
  expect(submitted).toEqual({
    plan: "paid_monthly",
    idempotencyKey: expect.any(String),
  });

  current = {
    ...current,
    plan: "PAID",
    status: "ACTIVE",
    paymentConfirmed: true,
    billingCountry: "IN",
    recurringAmountMinor: 19900,
    recurringCurrency: "INR",
    periodEnd: new Date(Date.now() + 86400_000).toISOString(),
  };
  await page.reload();
  const premium = page.getByRole("region", { name: "Premium", exact: true });
  await expect(premium).toBeVisible();
  await expect(premium.locator("[data-localized-price]")).toHaveCount(0);
  await expect(premium.locator("dd")).toHaveCount(0);
  await expect(premium.getByRole("meter")).toHaveCount(0);
  await expect(
    premium.getByRole("list", { name: "Included in your plan" }),
  ).toContainText("Unlimited");
  await expect(
    premium.getByText("Stored recurring amount before tax:", { exact: false }),
  ).toHaveCount(0);
  for (const width of [390, 280]) {
    await premium.locator("..").evaluate((el, width) => {
      el.style.width = `${width}px`;
    }, width);
    expect(
      await premium.evaluate((el) =>
        Array.from(el.querySelectorAll<HTMLElement>("*"))
          .filter(
            (child) =>
              child.clientWidth > 0 &&
              !child.classList.contains("sr-only") &&
              child.scrollWidth > child.clientWidth + 1,
          )
          .map((child) => ({ tag: child.tagName, text: child.textContent })),
      ),
      `Premium content fits at ${width}px`,
    ).toEqual([]);
    await premium.screenshot({
      path: testInfo.outputPath(`premium-${width}.png`),
      animations: "disabled",
      style: ".help-launcher, nextjs-portal { visibility: hidden !important; }",
    });
  }
  await premium
    .locator("..")
    .evaluate((el) => el.style.removeProperty("width"));
  await page.goto("/settings#plan");
  const settingsPlan = page.locator("#plan");
  await expect(
    settingsPlan.getByText("Stored recurring amount before tax:", {
      exact: false,
    }),
  ).toContainText("199.00 INR/month");
  await expect(
    settingsPlan.getByText("Next monthly renewal:", { exact: false }),
  ).toBeVisible();
  const menuTrigger = settingsPlan.getByRole("button", {
    name: "More subscription actions",
  });
  await expect(menuTrigger.locator("svg")).toBeVisible();
  await expect(menuTrigger).toHaveCSS("width", "44px");
  await menuTrigger.focus();
  await page.keyboard.press("ArrowDown");
  await expect(
    page.getByRole("menuitem", { name: "Refresh subscription status" }),
  ).toBeFocused();
  await page.keyboard.press("End");
  await expect(
    page.getByRole("menuitem", { name: "Contact support" }),
  ).toBeFocused();
  await page.keyboard.press("Escape");
  await expect(menuTrigger).toBeFocused();
  await page.setViewportSize({ width: 320, height: 850 });
  await expect(settingsPlan).toBeVisible();
  await settingsPlan.screenshot({
    path: testInfo.outputPath("settings-plan-320.png"),
    animations: "disabled",
    style: ".help-launcher, nextjs-portal { visibility: hidden !important; }",
  });
  expect(
    await page.evaluate(
      () => document.documentElement.scrollWidth <= innerWidth,
    ),
  ).toBe(true);
  await page.setViewportSize({ width: 1366, height: 1000 });
  let portalCalled = false;
  await page.route("**/api/billing/portal", (route) => {
    portalCalled = true;
    return route.fulfill({
      status: 503,
      json: { error: "Portal fixture unavailable" },
    });
  });
  await settingsPlan
    .getByRole("button", { name: "Manage subscription", exact: true })
    .click();
  await expect(settingsPlan.getByRole("alert")).toHaveText(
    "Portal fixture unavailable",
  );
  expect(portalCalled).toBe(true);
  await page.route("**/api/billing/cancel", (route) => {
    current = { ...current, cancellationPending: true };
    return route.fulfill({ json: { cancellationPending: true } });
  });
  await settingsPlan
    .getByRole("button", { name: "More subscription actions" })
    .click();
  await page.getByRole("menuitem", { name: "Cancel at period end" }).click();
  await expect(settingsPlan.getByRole("status")).toContainText(
    "Cancellation requested",
  );
  failedLookup = true;
  await settingsPlan
    .getByRole("button", { name: "More subscription actions" })
    .click();
  await page
    .getByRole("menuitem", { name: "Refresh subscription status" })
    .click();
  await expect(
    settingsPlan.getByText("Subscription status lookup temporarily failed.", {
      exact: false,
    }),
  ).toBeVisible();
  await expect(
    settingsPlan.getByRole("heading", { name: "Plan and subscription" }),
  ).toBeVisible();
  failedLookup = false;
  current = { ...current, cancellationPending: false, cancelAtPeriodEnd: true };
  await page.reload();
  await expect(
    settingsPlan.getByText("Cancellation scheduled.", { exact: false }),
  ).toBeVisible();
  await expect(
    settingsPlan.getByText("Next monthly renewal:", { exact: false }),
  ).toHaveCount(0);
  current = {
    ...current,
    cancelAtPeriodEnd: false,
    status: "PAST_DUE",
    gracePeriodEnd: "2027-01-02T00:00:00.000Z",
  };
  await page.reload();
  await expect(
    settingsPlan.getByText("Renewal payment needs attention.", {
      exact: false,
    }),
  ).toBeVisible();
  current = { ...current, status: "ACTIVE", isSuspended: true };

  await page.reload();
  await expect(settingsPlan).toContainText("Current plan: Premium");
  await expect(
    settingsPlan.getByRole("button", {
      name: "Manage subscription",
      exact: true,
    }),
  ).toBeEnabled();
  await expect(
    settingsPlan.getByText("Sending and Premium features are suspended.", {
      exact: false,
    }),
  ).toBeVisible();
  current = {
    ...current,
    plan: "FREE",
    status: "NONE",
    isSuspended: false,
    checkoutEnabled: false,
    mode: null,
  };
  await page.goto("/usage");
  await expect(
    card.getByRole("button", { name: "Upgrade to Premium", exact: true }),
  ).toBeDisabled();
  await expect(
    card.getByRole("button", { name: "Test mode", exact: true }),
  ).toHaveCount(0);
  await page.goto("/settings#plan");
  await expect(
    settingsPlan.getByText("Checkout is currently disabled."),
  ).toBeVisible();
  current = { ...current, status: "CANCELLED" };
  await page.reload();
  await expect(
    settingsPlan.getByText("Previous subscription", { exact: true }),
  ).toBeVisible();
  await settingsPlan
    .getByText("Previous subscription", { exact: true })
    .click();
  await expect(
    settingsPlan.getByText("Previous recurring amount before tax:", {
      exact: false,
    }),
  ).toContainText("199.00 INR/month");
});
